si[i++] = gsitm("N8040200R0000400ENG.html", "20. INHIBITOR SWITCH", "title");
si[i++] = gsitm("N8040200R0000400ENG.html", "On models with an automatic transmission, be sure the engine starts in both \"P\" and \"N\" position, and does not start in other positions.", "ptxt");
