si[i++] = gsitm("N8040200S0000400ENG.html", "Verify that the diesel engine revolution increases when the idle control knob is pulled out.", "ptxt");
si[i++] = gsitm("N8040200T0000400ENG.html", "22. INSTRUMENT PANEL CONTROLS", "title");
