si[i++] = gsitm("N8040200X0000400ENG.html", "26. OPERATION OF SERVICE BRAKES AND PARKING BRAKES", "title");
si[i++] = gsitm("N8040200X0000400ENG.html", "Service brakes", "ptxt");
