si[i++] = gsitm("N8040200Y0000400ENG.html", "27. CLUTCH OPERATION", "title");
si[i++] = gsitm("N8040200Y0000400ENG.html", "Check the clutch operation in all driving ranges.", "ptxt");
si[i++] = gsitm("N8040200Y0000400ENG.html", "Check the pedal to floorboard clearance when the clutch is just disengaged.", "ptxt");
