si[i++] = gsitm("N804020110000A00ENG.html", "On vehicles with speed limit warning system, perform the road test work under the following conditions to prepare the vehicle for \"34. Speed limit warning system activation\".", "ptxt");
si[i++] = gsitm("N804020110000A00ENG.html", "Mobile network reception available", "ptxt");
