si[i++] = gsitm("N804020110000A00ENG.html", "Verify that no black smoking is emitted from the end of the exhaust pipe (diesel-powered vehicles).", "ptxt");
si[i++] = gsitm("N804020120000400ENG.html", "30. TRANSMISSION IN ALL RANGES", "title");
si[i++] = gsitm("N804020120000400ENG.html", "Manual transmission", "ptxt");
si[i++] = gsitm("N804020120000400ENG.html", "Check the transmission in all forward ranges and in reverse.", "ptxt");
si[i++] = gsitm("N804020120000400ENG.html", "Automatic transmission", "ptxt");
si[i++] = gsitm("N804020120000400ENG.html", "Make sure shift indicator lines up properly in all ranges.", "ptxt");
si[i++] = gsitm("N804020120000400ENG.html", "Depress the accelerator completely to check that the manual kickdown is operating correctly.", "ptxt");
