si[i++] = gsitm("N804020130000400ENG.html", "Put the vehicle in gear and apply the brakes while the vehicle is in motion. Be sure brake operation is smooth and positive.", "ptxt");
si[i++] = gsitm("N804020130000400ENG.html", "Parking Brakes", "ptxt");
si[i++] = gsitm("N804020130000400ENG.html", "Stop the vehicle on a steep incline.", "ptxt");
si[i++] = gsitm("N804020130000400ENG.html", "With the service brakes firmly applied, place the transmission in \"N\" position, and set the parking brakes.", "ptxt");
si[i++] = gsitm("N804020130000400ENG.html", "Slowly release the service brakes to see if the parking brakes will hold.", "ptxt");
si[i++] = gsitm("N804020140000400ENG.html", "32. STEERING CONTROL", "title");
si[i++] = gsitm("N804020140000400ENG.html", "Check for excessive play or looseness.", "ptxt");
si[i++] = gsitm("N804020140000400ENG.html", "Check the steering wheel centre.", "ptxt");
si[i++] = gsitm("N804020150000400ENG.html", "33. VIBRATION AND RATTLES", "title");
si[i++] = gsitm("N804020150000400ENG.html", "Locate squeaks, rattles and unusual vibrations.", "ptxt");
si[i++] = gsitm("N804020150000400ENG.html", "Verify that no noise occurs from the engine, transmission, axle and body.", "ptxt");
si[i++] = gsitm("N8040201M0000201ENG.html", "34. SPEED LIMIT WARNING SYSTEM ACTIVATION &lt;OUTLANDER (GN#W) (VEHICLES FOR EUROPE)>", "title");
si[i++] = gsitm("N8040201M0000201ENG.html", "Check the activation state by using the combination meter.", "ptxt");
si[i++] = gsitm("N8040201M0000201ENG.html", "Select \"Driver Assistance\".", "ptxt");
si[i++] = gsitm("N8040201M0000201ENG.html", "Select \"Traffic Sign Assist\".", "ptxt");
si[i++] = gsitm("N8040201M0000201ENG.html", "Select \"License Information\".", "ptxt");
si[i++] = gsitm("N8040201M0000201ENG.html", "When \"License Expiration\" and \"License State Active\" is displayed, the speed limit warning system activation is complete.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "35. VEHICLE BOOTSTRAP VERIFICATION &lt;OUTLANDER (GN#W) (VEHICLES FOR EUROPE)>", "title");
si[i++] = gsitm("N8040201N0000200ENG.html", "Always follow safety precautions when starting the vehicle.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Connectivity process", "title");
si[i++] = gsitm("N8040201N0000200ENG.html", "Vehicle preparation", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Set the vehicle parking brake.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Turn the power supply mode of the electric motor switch to ON (READY indicator: OFF) for up to 6 minutes.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Turn the power supply mode of the electric motor switch to ON (READY indicator: ON) to start connectivity process.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "(The bootstrap process starts automatically when the electric motor switch is turned ON.)", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Wait for the green LED on the telematics switch to illuminate signaling connection confirmation. This process should take approximately 5 minutes.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Connection verification: Verify the green LED light on the telematics switch is on.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Did the green LED light turn on?", "question");
si[i++] = gsitm("N8040201N0000200ENG.html", "YES", "result");
si[i++] = gsitm("N8040201N0000200ENG.html", "GO TO 2.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "NO", "result");
si[i++] = gsitm("N8040201N0000200ENG.html", "GO TO 3.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Finalise bootstrap", "title");
si[i++] = gsitm("N8040201N0000200ENG.html", "To finalise bootstrap, perform the following steps.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Turn the power supply mode of the electric motor switch to OFF.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Open a door.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Close all doors.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Lock the door with the keyless operation key.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Without opening doors, wait for the green LED to turn off (for approximately 1 minute).", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Once the green LED turns off, unlock and open the door.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Wait for the green LED to turn on.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Work End", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Procedure to restart connectivity process", "title");
si[i++] = gsitm("N8040201N0000200ENG.html", "To restart the connectivity process, follow these steps:", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Locate the storage connector and pull it out.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Wait 2 minutes.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Unlock the door with the keyless operation key.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Press down the storage connector to restart the connectivity process.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "*: Only restart this process once", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Wait for the green LED to illuminate signaling connection confirmation. This process should take approximately 5 minutes.", "ptxt");
si[i++] = gsitm("N8040201N0000200ENG.html", "Replace the TCU. Then carry out the TCU replacement procedure. Refer to the Workshop Manual for work procedures.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "36. ELECTRICAL EQUIPMENT", "title");
si[i++] = gsitm("N804020160000D00ENG.html", "Radio", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Tune the radio to a local broadcasting station and check the following:", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Operate the volume, tone, balance and fader controls, etc.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Pull out the pushbuttons, dial another station and set each pushbuttons.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Operate the AM/FM switch.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Tape player", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Insert a cassette tape in the tape player and check as follows:", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the operation of the tape feeder and rewind.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the ejection.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the operation of volume, tone, balance and fader controls, etc.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Multivision display", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Operate the multivision display to check the following items:", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the operation of the map display, destination setting, search, etc.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the operation of the volume, tone, balance, fader, etc.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check the voice operation of the hands free function.", "ptxt");
si[i++] = gsitm("N804020160000D00ENG.html", "Check that the camera system is displayed.", "ptxt");
si[i++] = gsitm("N804020180000D00ENG.html", "37. IDLE SPEED", "title");
si[i++] = gsitm("N804020180000D00ENG.html", "Check the engine idle speed.", "ptxt");
si[i++] = gsitm("N804020180000D00ENG.html", "For specific idle speed adjustment procedure, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N804020190000D00ENG.html", "38. IGNITION TIMING", "title");
si[i++] = gsitm("N804020190000D00ENG.html", "Check the ignition timing. &lt;Except MPI vehicles with crankshaft-mounted crankshaft angle sensor>", "ptxt");
si[i++] = gsitm("N804020190000D00ENG.html", "For the inspection and adjustment of the ignition timing, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "39. RADIATOR COOLANT LEVEL", "title");
si[i++] = gsitm("N8040201A0000D00ENG.html", "Do not remove the radiator cap while the cooling system is under pressure.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "When removing the radiator cap, be careful of steam and boiling water.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "Add coolant only to the reserve tank if it is required.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "Check that the coolant level in the reserve tank is at or above \"LOW\" mark at normal engine operating temperature. And check cooling system for leaks.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "Check that the coolant concentration is 30% to 60%.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "If it is low, replenish the coolant to the reserve tank.", "ptxt");
si[i++] = gsitm("N8040201A0000D00ENG.html", "For the recommended coolant, refer to Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "40. HOSES, FLUID LINES AND CONNECTIONS LOCATED UNDER HOOD", "title");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Remember that the air conditioner system is under pressure.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Check all brake, fuel, power steering and air conditioner lines and connections;", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Verify proper routing, check connections for leaks, tighten loose connector as required.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Inspect routing and connections of all vacuum, and radiator and heater houses.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Keep in mind that an oily residue around an air conditioner connector does not necessarily indicate a leak.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Oil is used to lubricate fittings during assembly.", "ptxt");
si[i++] = gsitm("N8040201B0000D00ENG.html", "Be sure lines are not twisted or kinked.", "ptxt");
si[i++] = gsitm("N8040201E0000D00ENG.html", "41. ENGINE, TRANSMISSION, STEERING GEAR BOX AND DIFFERENTIAL FOR LEAKS", "title");
si[i++] = gsitm("N8040201E0000D00ENG.html", "Check the engine, transmission, steering gear box and differential for oil leaks.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "42. MANUAL TRANSMISSION AND TRANSFER (4WD) OIL LEVEL", "title");
si[i++] = gsitm("N8040201C0000D00ENG.html", "Gaskets (or packing) for the oil filler plug and the drain plug are non-reusable parts. Always replace them with new one, or oil leaks may be caused.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "Remove the filler plug.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "Check the oil level. If the oil level is at or slightly below the filler hole, it is in satisfactory condition.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "For oil level, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "If the level is low, replenish the transmission and transfer case with fresh oil by using a lubricator.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "For the specified oil, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "Renew a gasket, because it is a non-reusable part.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "Install the filler plug with a new gasket, and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N8040201C0000D00ENG.html", "For the specified torque, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201D0000D00ENG.html", "43. AUTOMATIC TRANSMISSION FLUID LEVEL", "title");
si[i++] = gsitm("N8040201D0000D00ENG.html", "Do not overfill.", "ptxt");
si[i++] = gsitm("N8040201D0000D00ENG.html", "Remove the dipstick and check the fluid level.", "ptxt");
si[i++] = gsitm("N8040201D0000D00ENG.html", "Fluid level is okay if it is in the specified range as illustration at normal engine operating temperature.", "ptxt");
si[i++] = gsitm("N8040201D0000D00ENG.html", "If the level is below the lower notch, replenish fluid until the level reaches the upper notch.", "ptxt");
si[i++] = gsitm("N8040201D0000D00ENG.html", "For the specified automatic transmission fluid, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "44. FRONT AND REAR DIFFERENTIAL OIL LEVELS", "title");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Gaskets (or packing) for the oil filler plug and the drain plug are non-reusable parts. Always replace them with new one, or oil leaks may be caused.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Remove the filler plug.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Check the oil level. If the oil level is at or slightly below the filler hole, it is in satisfactory condition.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Type 1", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Check the gear oil level.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "For oil level, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Type 2", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "If the level is low, replenish the front and/or rear differential with fresh oil by using a lubricator.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "For the specified oil, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Renew a gasket, because it is a non-reusable part.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "Install the filler plug with a new gasket, and tighten it to the specified torque.", "ptxt");
si[i++] = gsitm("N8040201F0000D00ENG.html", "For the specified torque, refer to GROUP 2, Periodic Inspection and Maintenance.", "ptxt");
si[i++] = gsitm("N8040201G0000D00ENG.html", "45. HOSES, FLUID LINES AND CONNECTIONS LOCATED UNDER VEHICLE", "title");
si[i++] = gsitm("N8040201G0000D00ENG.html", "Check all hoses, fluid lines and connections for leaks.", "ptxt");
si[i++] = gsitm("N8040201G0000D00ENG.html", "Check all hoses and fluid lines for proper routing away from sharp edges and moving components.", "ptxt");
si[i++] = gsitm("N8040201I0000D00ENG.html", "46. HEADLAMP AIMING", "title");
si[i++] = gsitm("N8040201I0000D00ENG.html", "Check condition for headlamp aiming.", "ptxt");
si[i++] = gsitm("N8040201I0000D00ENG.html", "For headlamp aiming procedures, refer to the Workshop Manual for that model.", "ptxt");
si[i++] = gsitm("N8040201J0000D00ENG.html", "47. EQUIPMENT", "title");
