si[i++] = gsitm("N8040201J0000D00ENG.html", "Jack, jack handle and tool set", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "48. EXTERIOR AND INTERIOR", "title");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Finally check and clean the exterior and interior.", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Wash the vehicle to remove all traces of road grime and other dirt on the vehicle as a result of new vehicle preparations.", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Clean exterior and interior glass surface.", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Remove all protective covers.", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Remove undercoat overspray, excess window sealer, and excess weatherstrip adhesive.", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Verify that the secondary key can not unlock the glove box and tailgate/boot lid (if so equipped).", "ptxt");
si[i++] = gsitm("N8040201K0000E00ENG.html", "Remove shipping and inspection stickers.", "ptxt");
si[i++] = gsitm("N8040201L0000D00ENG.html", "49. OWNER INSTRUCTIONS", "title");
si[i++] = gsitm("N8040201L0000D00ENG.html", "Verify that the owner\'s manual and service booklet is in the glove box.", "ptxt");
si[i++] = gsitm("N8040201L0000D00ENG.html", "Place the spare keys in envelope in the glove box before delivery.", "ptxt");
