si[i++] = gsitm("N802020030000D00ENG.html", "Remove the intercooler assembly at a position where they will not interfere with the removal and installation of ignition coil.", "ptxt");
si[i++] = gsitm("N802020030000D00ENG.html", "&lt;&lt;B>> SPARK PLUG REMOVAL", "title");
si[i++] = gsitm("N802020030000D00ENG.html", "Using special tool spark plug wrench (MB991398), remove the spark plug.", "ptxt");
si[i++] = gsitm("N802020030000D00ENG.html", "INSTALLATION SERVICE POINT", "title");
si[i++] = gsitm("N802020030000D00ENG.html", ">>A&lt;&lt; SPARK PLUG INSTALLATION", "title");
si[i++] = gsitm("N802020030000D00ENG.html", "In the same manner as removal, use special tool spark plug wrench (MB991398) to tighten the spark plug to the specified torque.", "ptxt");
si[i++] = gsitm("N802020030000D00ENG.html", "Tightening torque: 18 ± 2 N·m", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "CHECK VALVE CLEARANCE &lt;PR25DD>", "title");
si[i++] = gsitm("N802020040000G00ENG.html", "INSPECTION", "title");
si[i++] = gsitm("N802020040000G00ENG.html", "Perform inspection as follows after removal, installation or replacement of camshaft or valve-related parts, or if there is unusual engine conditions regarding valve clearance.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "Remove rocker cover.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "Measure the valve clearance with the following procedure:", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "Set No. 1 cylinder at TDC of its compression stroke.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "Rotate crankshaft pulley  clockwise and align TDC mark (no paint)  to timing indicator  on front cover.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", ": Paint marks (Not used for service)", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "At the same time, check that both intake and exhaust cam noses of No. 1 cylinder face inside () as shown in the figure.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", ": Camshaft (EXH)", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", ": Camshaft (INT)", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "If they do not face inside, rotate crankshaft pulley once more (360 degrees) and align as shown in the figure.", "ptxt");
si[i++] = gsitm("N802020040000G00ENG.html", "Use a feeler gauge, measure the clearance between valve lifter and camshaft.", "ptxt");
