si[i++] = gsitm("N802020040000F00ENG.html", "CHECK VALVE CLEARANCE &lt;4B4>", "title");
si[i++] = gsitm("N802020040000F00ENG.html", "Perform the valve clearance check and adjustment at the engine cold state.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Remove the cylinder head cover assembly.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Turn the crankshaft clockwise, and set the protrusion of the camshaft as shown in the figure. Therefore, No.1 cylinder goes to the compression top dead center.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Turn the crankshaft always clockwise.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Using a thickness gauge, measure the valve clearance with the arrow shown in Figure. If deviated from the standard value, make note for the valve clearance.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Standard value (cold engine)", "title");
si[i++] = gsitm("N802020040000F00ENG.html", "Intake side: 0.22 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Exhaust side: 0.30 ± 0.04 mm", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Turn the crankshaft clockwise 360 degrees. Therefore, No.4 cylinder goes to the compression top dead center.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Check the valve clearance with the arrow shown in Figure. In the same procedure as 3.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "If the valve clearance is deviated from the standard value, remove the camshaft and the valve tappet.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Using a micrometer, measure the thickness of the removed valve tappet.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Calculate the thickness of the newly installed valve tappet through the following equation.", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "A: thickness of newly installed valve tappet", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "B: thickness of removed valve tappet", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "C: measured valve clearance", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Equation", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Intake valve: A = B + (C - 0.22 mm)", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Exhaust valve: A = B + (C - 0.30 mm)", "ptxt");
si[i++] = gsitm("N802020040000F00ENG.html", "Every valve tappet has an identification mark stamped at the illustrated location.", "ptxt");
