si[i++] = gsitm("N802020070000Y00ENG.html", "WHEN DRAIN ENGINE COOLANT USING DRAIN HOSE", "title");
si[i++] = gsitm("N802020070000Y00ENG.html", "Never remove reservoir tank cap when engine is hot. Serious burns may occur from high-pressure engine coolant escaping from radiator.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Wrap a thick cloth around the reservoir tank cap. Slowly turn it a quarter of a turn to release built-up pressure. Then turn it all the way.", "ptxt");
