si[i++] = gsitm("N802020070000Y00ENG.html", "Refill MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Install reservoir tank if removed and radiator drain cock.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Be sure to clean drain cock and install with new O-ring.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "If water drain plugs on cylinder block are removed, close and tighten them.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Check that each hose clamp has been firmly tightened.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Fill radiator to specified level.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Never adhere the engine coolant to electronic equipment (alternator etc.).", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Pour coolant slowly of less than 3 (1-3/4 Imp qt) a minute to allow air in system to escape.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Engine coolant capacity (With reservoir tank at \"MAX\" level)", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "9.4 (8-3/10)", "ptxt");
