si[i++] = gsitm("N802020070000Y00ENG.html", "Install reservoir tank cap.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Warm up engine until opening thermostat. Standard for warming-up time is approximately 10 minutes at 3,000 rpm.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Check thermostat opening condition by touching radiator hose (lower) to see a flow of warm water.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Watch water temperature gauge so as not to overheat engine.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Stop the engine and cool down to less than approximately 50°C (122°F).", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Cool down using fan to reduce the time.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "If necessary, refill radiator up to filler neck with engine coolant.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Repeat steps 3 through 8 two or more times with radiator cap installed until engine coolant level no longer drops.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Check cooling system for leakage with engine running.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Warm up the engine, and check for sound of engine coolant flow while running engine from idle up to 3,000 rpm with heater temperature controller set at several position between \"COOL\" and \"WARM\".", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Sound may be noticeable at heater unit.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "Repeat step 11 three times.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "If sound is heard, bleed air from cooling system by repeating step 3 through 8 until reservoir tank level no longer drops.", "ptxt");
si[i++] = gsitm("N802020070000Y00ENG.html", "To avoid the blow out when the coolant is hot, never fill the coolant more than MAX level.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "CHANGE ENGINE COOLANT &lt;4B4>", "title");
si[i++] = gsitm("N802020070000X00ENG.html", "When removing the radiator reservoir tank cap, use care to avoid contact with hot engine coolant or steam. Place a shop towel over the radiator reservoir tank cap and turn the radiator reservoir tank cap counterclockwise a little to let the pressure escape through the vinyl tube. After relieving the steam pressure, remove the radiator reservoir tank cap by slowly turning it counterclockwise.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "When draining engine coolant, use a general-purpose hose (drain hose) with the dimensions show in the figure.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Remove the engine room under cover front B.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Connect drain hose.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Drain the water from the radiator, heater core and engine after unplugging the radiator drain plug and removing the radiator reservoir tank cap.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Remove the radiator reservoir tank and drain the coolant.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Disconnect drain hose.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Securely tighten the radiator drain plug.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Reinstall the radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Use special tool LLC changer (MB991871) to refill the engine coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Recommended antifreeze: MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent*", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "*similar high quality ethylene glycol based non-silicate, non-amine, non-nitrate and non-borate coolant with long life hybrid organic acid technology.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Quantity: Approximately 8.0 L", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Do not use alcohol or methanol anti-freeze or any engine coolants mixed with alcohol or methanol anti-freeze. The use of an improper anti-freeze can cause corrosion of the aluminum components.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Do not fill with engine coolant above the \"MAX\" line in the radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "For how to use special tool (MB991871), refer to its manufacturer\'s instructions.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Tighten the radiator reservoir tank cap securely.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Turn the A/C switch to OFF position to start the engine and warm up until the cooling fan operates.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Rev the engine several times and then stop it. Check that there are no coolant leaks.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Remove the radiator reservoir tank cap, and add the engine coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N802020070000X00ENG.html", "Install the engine room under cover front B.", "ptxt");
