si[i++] = gsitm("N802020170000700ENG.html", "Reinstall the intercooler radiator reservoir tank.", "ptxt");
si[i++] = gsitm("N802020170000700ENG.html", "Use special tool LLC changer (MB991871) to refill the intercooler coolant up to the \"MAX\" line.", "ptxt");
si[i++] = gsitm("N802020170000700ENG.html", "Recommended antifreeze: MITSUBISHI MOTORS GENUINE SUPER LONG LIFE COOLANT PREMIUM or equivalent*", "ptxt");
