si[i++] = gsitm("N802020170000700ENG.html", "Quantity: Approximately  3.2 L", "ptxt");
si[i++] = gsitm("N802020170000700ENG.html", "Do not use alcohol or methanol anti-freeze or any engine coolants mixed with alcohol or methanol anti-freeze. The use of an improper anti-freeze can cause corrosion of the aluminum components.", "ptxt");
si[i++] = gsitm("N802020170000700ENG.html", "Do not fill with intercooler coolant above the \"MAX\" line in the intercooler radiator reservoir tank.", "ptxt");
