si[i++] = gsitm("N802020140000100ENG.html", "CLEAN AIR CLEANER ELEMENT", "title");
si[i++] = gsitm("N802020140000100ENG.html", "Check air cleaner element for clogging and damage.", "ptxt");
si[i++] = gsitm("N802020140000100ENG.html", "Clean deposited dust from the element in the following manner.", "ptxt");
si[i++] = gsitm("N802020140000100ENG.html", "Lightly tap the element against the top of a bench.", "ptxt");
si[i++] = gsitm("N802020140000100ENG.html", "Blow compressed air from inside the element.", "ptxt");
si[i++] = gsitm("N802020140000100ENG.html", "Wipe off dust on the air cleaner interior.", "ptxt");
si[i++] = gsitm("N802020140000100ENG.html", "Install the air cleaner body.", "ptxt");
si[i++] = gsitm("N802020090000P00ENG.html", "REPLACE AIR CLEANER ELEMENT &lt;PR25DD>", "title");
si[i++] = gsitm("N802020090000P00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N802020090000P00ENG.html", "Release the clips  of air cleaner cover .", "ptxt");
si[i++] = gsitm("N802020090000P00ENG.html", ": Vehicle front", "ptxt");
si[i++] = gsitm("N802020090000P00ENG.html", "Remove air cleaner element.", "ptxt");
si[i++] = gsitm("N802020090000P00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N802020090000P00ENG.html", "Install in the reverse order of removal.", "ptxt");
si[i++] = gsitm("N802020090000O00ENG.html", "REPLACE AIR CLEANER ELEMENT", "title");
si[i++] = gsitm("N802020090000O00ENG.html", "The air cleaner element will become dirty and loaded with dust during use, and the filtering effect will be substantially reduced. Replace it with a new one.", "ptxt");
si[i++] = gsitm("N802020090000O00ENG.html", "Unclasp the air cleaner cover clamp.", "ptxt");
si[i++] = gsitm("N802020090000O00ENG.html", "Remove the air cleaner element and install a new one.", "ptxt");
si[i++] = gsitm("N802020090000O00ENG.html", "Be sure to close the air cleaner cover completely when clamping it.", "ptxt");
si[i++] = gsitm("N802020100000600ENG.html", "CHECK FLUID LEVEL IN BRAKE RESERVOIR", "title");
si[i++] = gsitm("N802020100000600ENG.html", "Check that the brake fluid level in the reservoir tank is within the standard (between MAX – MIN lines).", "ptxt");
si[i++] = gsitm("N802020100000600ENG.html", "Visually check for any brake fluid leakage around the reservoir tank.", "ptxt");
si[i++] = gsitm("N802020100000600ENG.html", "Check the brake system for any leakage if the fluid level is extremely low (lower than MIN).", "ptxt");
si[i++] = gsitm("N802020100000600ENG.html", "Check the brake system for fluid leakage if the warning light remains illuminated even after the parking brake is released.", "ptxt");
si[i++] = gsitm("N802020100000600ENG.html", "Check the reservoir tank for the mixing of foreign matter (e.g. dust) and oils other than brake fluid.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "CHANGE BRAKE FLUID", "title");
si[i++] = gsitm("N802020110000500ENG.html", "Never spill or splash brake fluid on painted surfaces. Brake fluid may seriously damage paint. Wipe it off immediately and wash with water if it gets on a painted surface. For brake component parts, never wash them with water.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Turn the ignition switch OFF and disconnect the ABS actuator and electric unit (control unit) harness connector or the battery negative terminal before performing work.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Draining", "title");
si[i++] = gsitm("N802020110000500ENG.html", "Connect a vinyl tube to the bleed valve.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Depress the brake pedal and loosen the bleeder valve to gradually discharge brake fluid.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Refilling", "title");
si[i++] = gsitm("N802020110000500ENG.html", "If fluid completely runs out of the reservoir tank during operation, air will find way into the brake line. Pay attention, therefore, to the fluid level and replenish as necessary.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Check that there is no foreign material in the reservoir tank, and refill with new brake fluid.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Never reuse drained brake fluid.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Never allow foreign matter (e.g. dust) and oils other than brake fluid to enter the reservoir tank.", "ptxt");
si[i++] = gsitm("N802020110000500ENG.html", "Loosen the bleeder valve, slowly depress the brake pedal to the full stroke, and then release the pedal. Repeat this operation at intervals of 2 or 3 seconds until new brake fluid is discharged. Then close the bleeder valve with the brake pedal depressed. Repeat the same work on each wheel.", "ptxt");
si[i++] = gsitm("N802020120000100ENG.html", "CHECK BATTERY CONDITION", "title");
si[i++] = gsitm("N802020120000100ENG.html", "Check that the battery electrolyte level is above the LOWER LEVEL indications. If the battery electrolyte level is below the LOWER LEVEL, replace the battery.", "ptxt");
si[i++] = gsitm("N802020120000100ENG.html", "If the battery is used with the electrolyte level below the LOWER LEVEL indicator, there is the danger that explosions may occur.", "ptxt");
si[i++] = gsitm("N802020120000100ENG.html", "Check the position of the terminal (whether it is securely inserted to the bottom) and check whether the tightening torque is within the specified range.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "REPLACE FUEL FILTER &lt;4B4>", "title");
si[i++] = gsitm("N802020130000F00ENG.html", "&lt;2WD>", "title");
si[i++] = gsitm("N802020130000F00ENG.html", "Release the fuel pressure in the fuel line.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Disconnect fuel main pipe quick connector according to the following instructions:", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Push in the retainer (orange, white) of the fuel main pipe connector and unlock the connector.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Disconnect the fuel main pipe from the fuel tank pump and gauge assembly.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Remove crossmember assembly &lt;Vehicles for 5 persons>.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Remove lock ring according to the following instructions.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Install pawl (B) of special tool unified fuel lock ring wrench (KV101207S0) (A) to the position shown in the figure.", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Temporarily tighten mounting bolt (B) of the pawl according to the measurement (R) from the center of special tool (KV101207S0) (A) to the end of pawl (C).", "ptxt");
si[i++] = gsitm("N802020130000F00ENG.html", "Set special tool (KV101207S0) to lock ring and tighten the mounting bolt of the pawl.", "ptxt");
