si[i++] = gsitm("N802050010000T00ENG.html", "The adjustment mechanisms of camber, caster, and kingpin inclination angles are not included.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If camber, caster, or kingpin inclination angle exceeds the standard value, check front suspension parts for wear and damage. Replace suspect parts if a malfunction is detected.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Kingpin inclination angle is reference value, no inspection is required.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Measure wheel alignment under unladen conditions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "\"Unladen conditions\" means that fuel, engine coolant, and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "PRELIMINARY CHECK", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "Check the following:", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Tires for improper air pressure.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Tires for improper wear.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Road wheels for runout.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Wheel bearing axial end play.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Transverse link ball joint axial end play.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Strut operation.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Each mounting part of axle and suspension for looseness and deformation.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Each of suspension member, strut assembly and transverse link for cracks, deformation and other damage.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "GENERAL INFORMATION AND RECOMMENDATIONS", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "A four-wheel thrust alignment should be performed.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "This type of alignment is recommended.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "The four-wheel \"thrust\" process helps ensure that the vehicle is properly aligned and the steering wheel is centered.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "The alignment rack itself should be capable.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "The rack should be checked to ensure that it is level.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Check the machine is properly calibrated.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Your alignment equipment should be regularly calibrated in order to give correct information.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Check with the manufacturer of your specific equipment for their recommended Service/Calibration Schedule.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "ALIGNMENT PROCESS", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "IMPORTANT:", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Use only the alignment specifications listed in this Service Manual.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "When displaying the alignment settings, many alignment machines use \"indicators\": (Green/red, plus or minus, Go/No Go). Never use these indicators.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "The alignment specifications programmed into your machine that operate these indicators may not be correct.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "This may result in an ERROR.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Most camera-type alignment machines are equipped with both \"Rolling Compensation\" method and optional \"Jacking Compensation\" method to \"compensate\" the alignment targets or head units. \"Rolling Compensation\" is the preferred method.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If using the \"Rolling Compensation\" method, after installing the alignment targets or head units, push or pull on the rear wheel to move the vehicle. Do not push or pull on the vehicle body.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If using the \"Jacking Compensation\" method, after installing the alignment targets or head units, raise the vehicle and rotate the wheels 1/2 turn both ways.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Do not use the \"Rolling Compensation\" method if you are using sensor-type alignment equipment.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Follow all instructions for the alignment machine you\'re using for more information.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "FRONT SUSPENSION ADJUSTMENT", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "TOE-IN", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "Loosen the steering outer socket, and then adjust the length using steering inner socket.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Item", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Standard", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Toe-in", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Total toe-in", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Distance", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Minimum", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Out 0.8 mm (Out 0.03 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Nominal", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 1.7 mm (In 0.07 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Maximum", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 4.2 mm (In 0.17 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Total toe-angle", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Degree minute", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "(Decimal degree)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Out 0° 04′ (Out 0.07°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 0°08\' (In 0.13°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 0° 20\' (In 0.33°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Measure value under unladen*2 conditions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "*1: A difference when assuming the left side a standard.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "*2: Fuel, engine coolant and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Always evenly adjust both toe-in alternately and adjust the difference between the left and right to the standard.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Always fix the steering inner socket when tightening the steering outer socket.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "After toe-in adjustment, adjust neutral position of steering angle sensor.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Perform steering torque calibration after toe-in adjustment.", "par1");
si[i++] = gsitm("N802050010000T00ENG.html", "After adjustment, check that the steering angle is within the standard range.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "FRONT WHEEL TURNING ANGLE", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "Perform toe-in inspection.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Perform front wheel turning angle inspection, after toe-in inspection.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Place front wheels on turning radius gauges and rear wheels on stands, so that vehicle can be level.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Check the maximum inner and outer wheel turning angles for LH and RH road wheels.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "With the engine at idle, turn steering wheel from full left stop to full right stop and measure the turning angles.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "A", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", ": Inner wheel angle", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "B", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", ": Outer wheel angle", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Steering Angle", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "Inner wheel", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "35° 30\' (35.5°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "38° 10\' (38.17°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "39° 40\' (39.67°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Outer wheel", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "32° 10\' (32.17°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Steering angles are not adjustable. Check steering gear assembly, steering column assembly, and front suspension components for wear or damage if any of the turning angles are different from the specified value. Replace any of them, if any non-standard condition exists.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "CAMBER, CASTER, KINGPIN", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "Camber", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Degree minute (Decimal degree)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "–1° 15\' (–1.25°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "–0° 30\' (–0.5°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "0° 15\' (0.25°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Left and right difference*1", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "[–0°45\' (–0.75°)] - [0° 45\' (0.75°)]", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Caster", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "4° 58\' (4.97°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "5° 43\' (5.72°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "6° 28\' (6.47°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "[–0° 30\' (–0.50°)] - [0° 30\' (0.50°)]", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Kingpin inclination", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "10° 42\' (10.70°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "11° 27\' (11.45°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "12° 12\' (12.20°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "REAR SUSPENSION ADJUSTMENT", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "CAMBER", "title");
si[i++] = gsitm("N802050010000T00ENG.html", "If camber is exceeds the standard value, adjust with adjusting bolt  in front lower link .", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "–1° 45\' (–1.75°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "–1° 00\' (–1.00°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "–0° 15\' (–0.25°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Measure value under unladen* conditions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "*: Fuel, engine coolant and lubricant are full. Spare tire, jack, hand tools and mats are in designated positions.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "When tightening the nut firmly and checking the torque, use a wrench to prevent the turning of the bolt.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "After adjusting camber, be sure to check toe-in.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If camber is not still within the specification, inspect and replace any damaged or worn suspension parts.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If toe-in is exceeds the standard value, adjust with adjusting bolt  in rear lower link .", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 0.0 mm (In 0.00 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 3.0 mm (In 0.12 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 6.0 mm (In 0.24 in)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Out 0° 04\' (Out 0.07)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 0° 14\' (In 0.23°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "In 0° 32\' (In 0.53°)", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "Be sure to adjust equally on right and left side with adjusting bolt.", "ptxt");
si[i++] = gsitm("N802050010000T00ENG.html", "If toe-in is not still within the specification, inspect and replace any damaged or worn suspension parts.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "CHECK FRONT AND REAR WHEEL BEARINGS FOR PLAY", "title");
si[i++] = gsitm("N802050020000800ENG.html", "Raise the vehicle.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "Rotate the tire to check whether the tire rotates smoothly without abnormal noise.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "Put your hands on the outer circumference of the tire and move it toward the axle to check that there is no looseness by feeling with your hands.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "If there is looseness, depress the brake pedal and check again whether the looseness disappears. If the looseness is still present, it is caused by the suspension components and it is not caused by the wheel bearing.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "If looseness is found in steps 2 through 4, check the bearing for looseness by using a dial gauge.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "&lt;WHEEL BEARING FOR PLAY MEASUREMENT>", "title");
si[i++] = gsitm("N802050020000800ENG.html", "Remove the wheel assembly and the brake pad assembly.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "Insert M12 plain washers, and tighten the nuts (M12 × 1.5) diagonally and evenly to the specified torque [113 N·m (11.5 kg-m, 83 ft-lb)] to secure the brake disc to the hub assembly.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "Set a dial gauge as shown in the figure. Move the hub in the axial direction and measure the end play.", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "Limit:", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "0.0 mm (0.0 in) or less &lt;Front>", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "0.05 mm (0.002 in) or less &lt;Rear>", "ptxt");
si[i++] = gsitm("N802050020000800ENG.html", "On completion, install the wheel assembly and the brake pad assembly.", "ptxt");
si[i++] = gsitm("N802050030000700ENG.html", "CHECK BRAKE HOSES AND PIPES FOR LEAKAGE", "title");
si[i++] = gsitm("N802050030000700ENG.html", "Check brake line (tubes and hoses) for cracks, deterioration or other damage. Replace any damaged parts.", "ptxt");
si[i++] = gsitm("N802050030000700ENG.html", "Depress the brake pedal with a force of 785 N (80 kg, 176 lb) and hold down the pedal for approximately 5 seconds with the engine running. Check for any fluid leakage.", "ptxt");
si[i++] = gsitm("N802050030000700ENG.html", "Retighten the applicable connection to the specified torque and repair any abnormal (damaged, worn or deformed) part if any brake fluid leakage is present.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "CHECK BRAKE PADS AND DISCS FOR WEAR", "title");
si[i++] = gsitm("N802050040000700ENG.html", "FRONT BRAKE PAD INSPECTION", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Check brake pad wear thickness from an inspection hole on cylinder body. Check using a scale if necessary.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Item", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Limit", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Brake pad", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Wear thickness", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "2.0 (0.079)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "REAR BRAKE PAD INSPECTION", "title");
si[i++] = gsitm("N802050040000700ENG.html", "2.0 (0.0079)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "BRAKE PAD ADJUSTMENT", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Burnish contact surfaces between disc rotor and brake pads according to the following procedure after refinishing or replacing brake pads, or if a soft pedal occurs at very low mileage.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Be careful of vehicle speed because the brake does not operate firmly/securely until pads and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Only perform this procedure under safe road and traffic conditions. Use extreme caution.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Drive vehicle on straight, flat road.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Depress brake pedal with the power to stop vehicle within 3 to 5 seconds until the vehicle stops.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Drive without depressing brake for a few minutes to cool the brake.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Repeat steps 1 to 3 until pad and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "FRONT BRAKE DISC INSPECTION", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Appearance", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Check surface of disc rotor for uneven wear, cracks, and serious damage. Replace it if necessary.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Runout", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Fix the disc rotor to the wheel hub and bearing assembly with wheel nuts (2 points at least).", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Check the wheel bearing axial end play.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Inspect the runout with a dial indicator to measure at 10 mm (0.39 in) inside the disc edge.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Disc rotor", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Runout (with it attached to the vehicle)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "0.035 (0.0014)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Find the installation position that has a minimum runout by shifting the disc rotor-to-wheel hub and bearing assembly installation position by one hole at a time if the runout exceeds the limit value.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Refinish the disc rotor if the runout is outside the limit even after performing the above operation.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Check in advance that the thickness of the disc rotor is wear thickness + 0.3 mm (0.012 in) or more.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "If the thickness is less than wear thickness + 0.3 mm (0.012 in), replace the disc rotor.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "27.4 (1.079)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Thickness", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Check the thickness of the disc rotor using a micrometer. Measure the brake disc thickness at minimum eight points which are 10 mm (0.39 inch) inward from its circumference. Replace the disc rotor if the thickness is below the wear limit.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Thickness variation (measured at 8 positions)*", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "0.020 (0.0008)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "*To check if rotor imbalance, rotor runout or rotor deformation is occurred.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "REAR BRAKE DISC INSPECTION", "title");
si[i++] = gsitm("N802050040000700ENG.html", "0.070 (0.0028)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "14.0 (0.551)", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "BRAKE DISC ADJUSTMENT", "title");
si[i++] = gsitm("N802050040000700ENG.html", "Burnish contact surfaces between disc rotors and brake pads according to the following procedure after refinishing or replacing disc rotor, or if a soft pedal occurs at very low mileage.", "ptxt");
si[i++] = gsitm("N802050040000700ENG.html", "Be careful of vehicle speed because the brake does not operate firmly/securely until pad and disc rotor are securely fitted.", "ptxt");
si[i++] = gsitm("N802050050000700ENG.html", "CHECK FUEL HOSES AND PIPES FOR LEAKAGE OR DETERIORATION", "title");
si[i++] = gsitm("N802050050000700ENG.html", "Inspect fuel lines, fuel filler cap, and fuel tank for improper attachment, leakage, cracks, damage, loose connections, chafing or deterioration.", "ptxt");
si[i++] = gsitm("N802050050000700ENG.html", ": Engine", "ptxt");
si[i++] = gsitm("N802050050000700ENG.html", ": Fuel line", "ptxt");
si[i++] = gsitm("N802050050000700ENG.html", ": Fuel tank", "ptxt");
si[i++] = gsitm("N802050050000700ENG.html", "If necessary, repair or replace damaged parts.", "ptxt");
si[i++] = gsitm("N802060010000700ENG.html", "CHECK CVT FOR FLUID LEAKAGE &lt;F1CJD, W1CJD>", "title");
si[i++] = gsitm("N802060010000700ENG.html", "Check transaxle surrounding area (oil seal and plug etc.) for fluid leakage.If there is fluid leakage, repair the appropriate part.", "ptxt");
si[i++] = gsitm("N802060010000600ENG.html", "CHECK CVT FOR FLUID LEAKAGE &lt;F1CJE, W1CJE>", "title");
si[i++] = gsitm("N802060010000600ENG.html", "Check transaxle surrounding area (oil seal and plug etc.) for fluid leakage.", "ptxt");
si[i++] = gsitm("N802060010000600ENG.html", "If transaxle appears to have oil seepage or a leak, follow the steps below to assist in a correct diagnosis.", "ptxt");
si[i++] = gsitm("N802060010000600ENG.html", "If anything is found, repair or replace damaged parts and adjust CVT fluid level.", "par1");
si[i++] = gsitm("N802060020000800ENG.html", "CHANGE CVT FLUID &lt;F1CJD, W1CJD>", "title");
si[i++] = gsitm("N802060020000800ENG.html", "CVT fluid and fluid capacity", "ptxt");
si[i++] = gsitm("N802060020000800ENG.html", "Recommended Fluids/Lubricants", "ptxt");
si[i++] = gsitm("N802060020000800ENG.html", "Fluid capacity", "par10");
si[i++] = gsitm("N802060020000800ENG.html", "MITSUBISHI MOTORS GENUINE CVTF-J4 or MITSUBISHI MOTORS GENUINE CVTF-J4+", "ptxt");
si[i++] = gsitm("N802060020000800ENG.html", "Use only \"Mitsubishi Motors Genuine CVTF-J4\" or \"Mitsubishi Motors Genuine CVTF-J4+\" transmission fluid to ensure optimum transmission performance.", "ptxt");
si[i++] = gsitm("N802060020000800ENG.html", "7.9 liter (7 imp qt)", "ptxt");
si[i++] = gsitm("N802060020000800ENG.html", "Always use shop paper. Never use shop cloth.", "ptxt");
