si[i++] = gsitm("N802060030001D00ENG.html", "CHANGE ENGINE OIL &lt;PR25DD>", "title");
si[i++] = gsitm("N802060030001D00ENG.html", "Draining", "title");
si[i++] = gsitm("N802060030001D00ENG.html", "Be careful not to get burned, as engine oil may be hot.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Prolonged and repeated contact with used engine oil may cause skin cancer. Try to avoid direct skin contact with used engine oil. If skin contact is made, wash thoroughly with soap or hand cleaner as soon as possible.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Warm up the engine, and check for engine oil leakage from engine components.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Stop the engine and wait for 10 minutes.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Loosen oil filler cap.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Remove drain plug and then drain engine oil.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Refilling", "title");
si[i++] = gsitm("N802060030001D00ENG.html", "Install drain plug with new drain plug washer.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Do not reuse drain plug washer.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Be sure to clean drain plug and install with new drain plug washer.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Tightening torque", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", ": 34.3 N·m (3.5 kg-m, 25 ft-lb)", "ptxt");
