si[i++] = gsitm("N802060030001D00ENG.html", "Drain and refill", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "With oil filter change", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "5.1 (4-1/2)", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Genuine \"MITSUBISHI MOTORS GENUINE MOTOR OIL SN or SP 0W-20\" is recommended &lt;Except vehicles for Australia and New Zealand>.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Genuine \"MITSUBISHI MOTORS GENUINE MOTOR OIL SN or SP\" is recommended &lt;Vehicles for Australia and New Zealand>.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "If the above motor oil (or engine oil) is not available, use the equivalent of \"MITSUBISHI MOTORS GENUINE MOTOR OIL\" that matches the following grade and viscosity.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Oil grade: API SN or SP, ILSAC GF-5 or GF-6A", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "SAE Viscosity: See \"Recommended SAE viscosity number\"", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Damage caused by the use of motor oil (or engine oil) other than as recommended is not covered under Mitsubishi Motor\'s New Vehicle Limited warranty.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Without oil filter change", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "4.8 (4-1/4)", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "The refill capacity depends on the engine oil temperature and drain time. Use these specifications for reference only.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Always use oil level gauge to determine the proper amount of engine oil in the engine.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Warm up engine and check area around drain plug and oil filter for engine oil leakage.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Stop engine and wait for 10 minutes.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "Check the engine oil level.", "ptxt");
si[i++] = gsitm("N802060030001D00ENG.html", "RECOMMENDED SAE VISCOSITY NUMBER", "title");
si[i++] = gsitm("N802060030001D00ENG.html", "Select engine oil of the proper SAE viscosity number according to the atmospheric temperature.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "CHANGE ENGINE OIL &lt;4B4>", "title");
si[i++] = gsitm("N802060030001C00ENG.html", "Start the engine and allow it to warm up until the temperature of the coolant reaches 80°C to 90°C.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Remove the engine oil filler cap.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Use care as engine oil could be hot.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Remove the engine room under cover front B.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Remove the engine oil pan drain plug to drain engine oil.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Install a new engine oil pan drain plug gasket and then tighten the engine oil pan drain plug to the specified torque.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Tightening torque: 39 ± 5 N·m", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Refill with specified quantity of engine oil.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Specified engine oil:", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Select engine oil of the proper SAE viscosity number according to the atmospheric temperature.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "It is recommended to use engine oil that complies with API classification.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "API classification: “For service SN” or higher.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "If using oils other than those mentioned above, use one of the following types.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "ILSAC certificated oil", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "ACEA classification:", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "“For service A3/B3, A3/B4, or A5/B5”*", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "*: Only oils that simultaneously meet API classification“SN or higher” are permitted.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "SAE 0W-20, 0W-30, 5W-20, 5W-30 and 5W-40 engine oils can only be used if they meet ACEA A3/B3, A3/B4 or A5/B5 and API “SN or higher” specifications.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Engine oil quantity:", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "With oil filter change: Approximately 4.3 L", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Without oil filter change: Approximately 4.1 L", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil is recommended for optimum fuel economy and cold weather starting.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "If Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil is not available, 5W-20 grade oils displaying the ILSAC certification can be used. However, Mitsubishi Motors Genuine 0W-20 Synthetic Engine Oil should be used at the next oil change to maintain optimum fuel economy and cold weather starting.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Install the engine oil filler cap.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Let the engine run for a few minutes.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Stop the engine, and then check the engine oil level using the engine oil dipstick after a few minutes.", "ptxt");
si[i++] = gsitm("N802060030001C00ENG.html", "Install the engine room under cover front B.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "REPLACE ENGINE OIL FILTER &lt;PR25DD>", "title");
si[i++] = gsitm("N802060040000S00ENG.html", "REMOVAL", "title");
si[i++] = gsitm("N802060040000S00ENG.html", "Using oil filter wrench [SST: KV10115801], remove oil filter .", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", ": Engine front", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Oil filter is provided with relief valve. Use Mitsubishi Genuine Oil Filter or equivalent.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Be careful not to get burned when engine and engine oil may be hot.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "When removing, prepare a shop cloth to absorb any engine oil leakage or spillage.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Completely wipe off any engine oil that adheres to engine and vehicle.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "INSTALLATION", "title");
si[i++] = gsitm("N802060040000S00ENG.html", "Remove foreign materials adhering to the oil filter installation surface.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Apply new engine oil to the oil seal contact surface of new oil filter.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Screw oil filter manually until it touches the installation surface, then tighten it by 2/3 turn . Or tighten to specification.", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", "Oil filter:", "ptxt");
si[i++] = gsitm("N802060040000S00ENG.html", ": 17.7 N·m (1.8 kg-m, 13 ft-lb)", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "REPLACE ENGINE OIL FILTER &lt;4B4>", "title");
si[i++] = gsitm("N802060040000R00ENG.html", "Remove the engine oil pan drain plug to drain engine oil.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Use special tool oil filter wrench (MB991396) or commercially-available tool to remove the engine oil filter.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Clean the engine oil filter installing surface on the engine oil filter bracket side.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Apply a small amount of engine oil to the new engine oil filter O-ring.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Tighten the engine oil filter until the O-ring contacts with the installation surface.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "In the same manner as removal, use special tool oil filter wrench (MB991396) or commercially-available tool to tighten the engine oil filter to the specified torque.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Tightening torque: Approximately 1 turn (14 ± 2 N·m)", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Install the engine oil pan drain plug and refill the engine oil.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Rev the engine a few times, and check to be sure that no engine oil leaks from the installation section of the engine oil filter.", "ptxt");
si[i++] = gsitm("N802060040000R00ENG.html", "Install the engine room under cover front B.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "CHECK CO CONCENTRATION (PETROL-POWERED VEHICLES) &lt;ONLY IN THE COUNTRY WHICH IS NECESSARY BY REGULATION>", "title");
si[i++] = gsitm("N802060110000100ENG.html", "Before inspection, set the vehicle to the pre-inspection condition.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Turn the ignition switch to the \"LOCK\" (OFF) position and then connect the M.U.T.-III SE to the diagnosis connector.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Start the engine and let it run at idle.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Check that ignition timing is at the standard value.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Standard value: approximately 10° BTDC", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "The ignition timing may fluctuate within ±7°. This is normal.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "In higher altitude, the ignition timing is more advanced than the standard value by approximately 5°.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Wait till approximately 1 minute passes after the engine started, and check the ignition timing when the engine stabilized.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Check the idle speed.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Standard value: 850 ± 100 r/min", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "The idle speed is controlled automatically by the idle speed control system.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "When using the M.U.T.-III SE, select item No. 3 and take a reading of the idle speed.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "If the idle speed is outside the standard value, inspect the MFI system.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Run the engine at 2,000 - 3,000 r/min for 2 minutes.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Set the CO, HC tester.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Check the CO contents and the HC contents at idle.", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "Standard value", "title");
si[i++] = gsitm("N802060110000100ENG.html", "CO contents: 0.5 % or less", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "HC contents: 100 ppm or less", "ptxt");
si[i++] = gsitm("N802060110000100ENG.html", "If there is a deviation from the standard value, inspect the MFI system.", "ptxt");
